package com.acttub.actingapi.auth;
import static org.assertj.core.api.Assertions.*; import java.util.UUID; import jakarta.servlet.http.HttpServletRequest; import org.junit.jupiter.api.Test; import com.acttub.actingapi.domain.UserStatus; import com.acttub.actingapi.web.ApiException;
class AuthDependenciesTest {@Test void fourCompositionsPreserveOptionalRateAndConsentSemantics(){var user=new AuthStore.User(UUID.randomUUID(),null,UserStatus.ACTIVE);CurrentUserService current=new CurrentUserService(null,null){@Override public AuthStore.User optional(HttpServletRequest request){return null;}@Override public AuthStore.User require(HttpServletRequest request){return user;}};AuthStore store=new AuthStore(null,null){@Override public boolean hasPendingConsents(UUID ignored){return true;}};HttpServletRequest request=null;FixedWindowRateLimiter limiter=new FixedWindowRateLimiter(()->1L);AuthDependencies deps=new AuthDependencies(current,limiter,store);assertThat(deps.optionalUser(request)).isNull();assertThat(deps.currentUser(request)).isEqualTo(user);assertThat(deps.rateLimitedUser(request)).isEqualTo(user);assertThatThrownBy(()->deps.consentedUser(request)).isInstanceOf(ApiException.class).hasMessage("consent_required");}}
